import { FC } from 'react';

interface PickerOption {
    label: string;
    value: string | number;
    disabled?: boolean;
    children?: PickerOption[];
}
interface PickerColumn {
    options: PickerOption[];
    defaultValue?: string | number;
}
interface PickerViewProps {
    /** 单列选项 */
    options?: PickerOption[];
    /** 多列选项 */
    columns?: PickerColumn[];
    /** 当前值 (受控) */
    value?: (string | number)[];
    /** 默认值 (非受控) */
    defaultValue?: (string | number)[];
    /** 值变化回调 */
    onChange?: (value: (string | number)[], options: PickerOption[]) => void;
    /** 可见行数 */
    visibleCount?: number;
    /** 行高 (rpx) */
    itemHeight?: number;
    /** 自定义类名 */
    className?: string;
}
interface PickerProps extends PickerViewProps {
    /** 是否打开 */
    open: boolean;
    /** 标题 */
    title?: string;
    /** 确认按钮文字 */
    confirmText?: string;
    /** 取消按钮文字 */
    cancelText?: string;
    /** 点击确认回调 */
    onConfirm?: (value: (string | number)[], options: PickerOption[]) => void;
    /** 点击取消/关闭回调 */
    onCancel?: () => void;
    /** 关闭回调 (确认或取消都会触发) */
    onClose?: () => void;
}

declare const PickerView: FC<PickerViewProps>;

declare const Picker: FC<PickerProps>;

export { Picker, PickerView, Picker as default };
export type { PickerColumn, PickerOption, PickerProps, PickerViewProps };
